package com.billingcopilot.service;
import com.billingcopilot.model.BillingModels.*; import com.billingcopilot.repository.ContractBillingRuleRepository; import org.springframework.stereotype.Service; import java.util.List;
@Service public class ContractAuditService { private final ContractBillingRuleRepository rules; private final ReconciliationService reconciliation; public ContractAuditService(ContractBillingRuleRepository r,ReconciliationService s){rules=r;reconciliation=s;} public AuditResult audit(long contractId,List<WorkItem> work,List<InvoiceItem> invoice){var approved=rules.findByContractDocumentIdAndReviewStatusOrderById(contractId,"APPROVED").stream().map(r->new BillingRule(r.getService(),r.getRate(),r.getUnit())).toList(); if(approved.isEmpty()) throw new IllegalStateException("Approve at least one contract rule before running an audit"); return reconciliation.audit(new AuditRequest(approved,work,invoice));}}
